public void init()
{
    next init();

    QueryBuildDataSource qbds = this.query().dataSourceTable(tableNum(DirPartyPostalAddressView));
    qbds.addLink(fieldNum(smmBusRelTable, Party), fieldNum(DirPartyPostalAddressView, Party), tableStr(smmBusRelTable));

    this.addAddressQueryRanges();
}

/// <summary>
///     AVA <c>executeQuery</c> method.
