/// <summary>
///     AVA <c>addAddressQueryRanges</c> method.
/// </summary>
public void addAddressQueryRanges()
{
    QueryBuildDataSource qbds;

    qbds = this.query().dataSourceTable(tableNum(DirPartyPostalAddressView));

    qbds.addRange(fieldNum(DirPartyPostalAddressView, IsPrimary)).value(queryValue(NoYes::Yes));
    qbds.addRange(fieldnum(DirPartyPostalAddressView, IsPrivate)).value(queryValue(NoYes::No));
    qbds.addRange(fieldNum(DirPartyPostalAddressView, ValidFrom)).value(queryRange(DateTimeUtil::minValue(),  DateTimeUtil::getSystemDateTime()));
    qbds.addRange(fieldNum(DirPartyPostalAddressView, ValidTo)).value(queryRange(DateTimeUtil::getSystemDateTime(),  DateTimeUtil::maxValue()));
}
